<?php
declare(strict_types=1);
function geoip_install_from_url(string $url,?string $account=null,?string $license=null):array{
    $root=dirname(__DIR__);$target=$root.'/geoip/GeoLite2-City.mmdb';$tmp=$root.'/geoip/.GeoLite2-City.download';$headers=['User-Agent: PocketCat-GeoLite2-Updater/1.1','Accept: application/octet-stream, application/gzip, application/x-gzip, */*'];if($account&&$license)$headers[]='Authorization: Basic '.base64_encode($account.':'.$license);
    $ch=curl_init($url);$fp=fopen($tmp,'wb');if(!$fp)throw new RuntimeException('Cannot create GeoIP temporary file.');curl_setopt_array($ch,[CURLOPT_FILE=>$fp,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>180,CURLOPT_HTTPHEADER=>$headers,CURLOPT_FAILONERROR=>true]);$ok=curl_exec($ch);$err=curl_error($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);fclose($fp);if(!$ok){@unlink($tmp);throw new RuntimeException('GeoIP download failed (HTTP '.$status.'): '.($err?:'unknown error'));}
    $raw=@file_get_contents($tmp);$installed=false;if($raw!==false && strlen($raw)>1024 && strrpos($raw,"\xAB\xCD\xEFMaxMind.com")!==false){$installed=(bool)file_put_contents($target,$raw);}
    if(!$installed && $raw!==false && substr($raw,0,2)==="\x1f\x8b"){$decoded=@gzdecode($raw);if($decoded!==false&&strlen($decoded)>1024&&strrpos($decoded,"\xAB\xCD\xEFMaxMind.com")!==false){$installed=(bool)file_put_contents($target,$decoded);}}
    if(!$installed && $raw!==false && substr($raw,0,2)==="\x1f\x8b"){
        try{$phar=new PharData($tmp);$tar=$tmp.'.tar';if(!file_exists($tar))$phar->decompress();$tarPhar=new PharData($tar);foreach(new RecursiveIteratorIterator($tarPhar) as $file){if((string)$file->getFilename()==='GeoLite2-City.mmdb'){$installed=copy((string)$file->getPathname(),$target);break;}}@unlink($tar);}catch(Throwable $e){}
    }
    @unlink($tmp);if(!$installed||!is_file($target)||filesize($target)<1024)throw new RuntimeException('Downloaded file did not contain a valid GeoLite2-City database.');if(class_exists('PocketCatMaxMindReader')){try{$verify=new PocketCatMaxMindReader($target);$meta=$verify->metadata();$verify->close();if((int)($meta['node_count']??0)<1||!in_array((int)($meta['record_size']??0),[24,28,32],true)||!in_array((int)($meta['ip_version']??0),[4,6],true))throw new RuntimeException('Downloaded GeoIP database metadata is invalid.');}catch(Throwable $e){throw new RuntimeException('Downloaded GeoIP database failed local validation: '.$e->getMessage());}}return ['path'=>$target,'size'=>(int)filesize($target)];
}
